-- Migration 919: import Flock 20's flock-level grade-wise egg data
-- (Egg sheet, Received columns) for the two real gaps not covered by
-- the app's own live entries: 2025-11-02..11-19 and 2025-12-01..2026-05-31.
-- Insert-only, shed_id=NULL (flock-level rows), tagged for traceability.
-- No existing rows (per-shed or the 95 existing flock-level rows) are touched.









SELECT 'f919_import_count' AS chk, count(*)::int AS n
  FROM public.daily_records WHERE remarks = 'F20_EGGGRADE_IMPORT_2026-08-25';